insert into public.quiz_questions (lesson_id, sort, prompt, options, correct_index, explanation) values
  ('unix-01', 1, 'A central tenet of the Unix philosophy is to…', '["Build one giant program", "Write small tools that do one thing well and compose them", "Avoid the command line", "Never use text"]'::jsonb, 1, 'Small, composable, single-purpose tools.'),
  ('unix-01', 2, 'In Unix, ''everything is a…''', '["file", "printer", "window", "registry key"]'::jsonb, 0, 'Devices, pipes, and more are exposed as files.'),
  ('unix-01', 3, 'Composability is achieved largely through…', '["the registry", "pipes and plain-text streams", "GUIs", "email"]'::jsonb, 1, 'Text streams piped between tools.'),
  ('unix-02', 1, 'A POSIX shell script usually starts with…', '["a shebang line like #!/bin/sh", "<html>", "// comment", "import os"]'::jsonb, 0, 'The shebang selects the interpreter.'),
  ('unix-02', 2, 'Which captures command output into a variable?', '["x=$(command)", "x == command", "print(command)", "command > x only"]'::jsonb, 0, 'Command substitution $( ) captures output.'),
  ('unix-02', 3, 'An exit status of 0 conventionally means…', '["failure", "success", "unknown", "timeout"]'::jsonb, 1, '0 = success; non-zero = error.'),
  ('unix-03', 1, 'FreeBSD, OpenBSD and NetBSD are examples of…', '["Windows editions", "BSD Unix systems", "Linux distros", "hypervisors"]'::jsonb, 1, 'They are BSD-derived Unix systems.'),
  ('unix-03', 2, 'OpenBSD is particularly known for…', '["gaming", "a strong security focus", "spreadsheets", "printing"]'::jsonb, 1, 'OpenBSD emphasises security and code correctness.'),
  ('unix-03', 3, 'BSD systems are licensed under…', '["GPL only", "the permissive BSD license", "a closed EULA", "no license"]'::jsonb, 1, 'The BSD license is permissive.'),
  ('unix-04', 1, 'An ACL extends standard Unix permissions by…', '["removing all access", "allowing per-user/per-group entries beyond owner/group/other", "encrypting files", "hiding files"]'::jsonb, 1, 'ACLs grant finer-grained access than ugo.'),
  ('unix-04', 2, 'The setuid bit causes a program to run with…', '["no permissions", "the file owner''s privileges", "guest only", "root removed"]'::jsonb, 1, 'setuid runs with the owner''s rights.'),
  ('unix-04', 3, 'Which sets read/write/execute for owner only (octal)?', '["700", "777", "644", "000"]'::jsonb, 0, '700 = rwx for owner, nothing for others.'),
  ('unix-05', 1, 'Sending SIGTERM to a process asks it to…', '["start", "terminate gracefully", "sleep forever", "fork"]'::jsonb, 1, 'SIGTERM requests a clean shutdown.'),
  ('unix-05', 2, 'SIGKILL (-9) differs because it…', '["can be ignored", "cannot be caught and forcibly kills", "restarts the process", "pauses it"]'::jsonb, 1, 'SIGKILL is unconditional and uncatchable.'),
  ('unix-05', 3, 'Which lists running processes?', '["ps (or top)", "ls", "cd", "cat"]'::jsonb, 0, 'ps/top show process information.'),
  ('networking-01', 1, 'How many layers does the OSI model have?', '["7", "4", "5", "3"]'::jsonb, 0, 'OSI has 7 layers.'),
  ('networking-01', 2, 'Routing and IP addressing happen at the OSI…', '["Physical layer", "Network layer (3)", "Application layer", "Session layer"]'::jsonb, 1, 'Layer 3 is the Network layer.'),
  ('networking-01', 3, 'MAC addresses operate at the…', '["Data Link layer (2)", "Transport layer", "Application layer", "Network layer"]'::jsonb, 0, 'MAC is a layer-2 (Data Link) concept.'),
  ('networking-02', 1, 'TCP is best described as…', '["connectionless", "connection-oriented and reliable", "unroutable", "a cable type"]'::jsonb, 1, 'TCP provides reliable, ordered delivery.'),
  ('networking-02', 2, 'UDP is preferred when you need…', '["guaranteed delivery", "low overhead/speed over reliability", "encryption", "routing"]'::jsonb, 1, 'UDP trades reliability for speed/low overhead.'),
  ('networking-02', 3, 'An IPv4 address is how many bits?', '["32", "64", "128", "16"]'::jsonb, 0, 'IPv4 = 32 bits.'),
  ('networking-03', 1, 'A /24 network provides how many usable host addresses?', '["254", "256", "510", "64"]'::jsonb, 0, '256 minus network+broadcast = 254 usable.'),
  ('networking-03', 2, 'CIDR notation /26 means the subnet mask is…', '["255.255.255.192", "255.255.255.0", "255.255.0.0", "255.255.255.255"]'::jsonb, 0, '/26 = 255.255.255.192.'),
  ('networking-03', 3, 'Subnetting is used to…', '["slow networks", "divide a network into smaller segments", "remove IPs", "disable routing"]'::jsonb, 1, 'Subnets segment a larger network.'),
  ('networking-04', 1, 'A VLAN primarily provides…', '["faster cables", "logical network segmentation on shared switches", "more storage", "encryption"]'::jsonb, 1, 'VLANs segment traffic logically.'),
