  ('networking-04', 3, 'Switches forward frames using…', '["IP addresses", "MAC address tables", "DNS", "ports only"]'::jsonb, 1, 'Switches learn and use MAC tables.'),
  ('networking-05', 1, 'A router''s job is to…', '["broadcast everything", "forward packets between different networks", "store files", "assign passwords"]'::jsonb, 1, 'Routers move packets between networks.'),
