  ('troubleshooting-03', 3, 'A service that won''t start is inspected with…', '["systemctl status <svc>", "format", "reboot only", "cd"]'::jsonb, 0, 'systemctl status shows why it failed.'),
  ('troubleshooting-04', 1, 'To test reachability to a host you use…', '["ping", "chmod", "df", "ls"]'::jsonb, 0, 'ping tests basic reachability.'),
  ('troubleshooting-04', 2, 'To trace the path packets take you use…', '["traceroute/tracert", "cat", "top", "kill"]'::jsonb, 0, 'traceroute maps the hop path.'),
